  1	//! Exec implements the logic for starting and stopping a subprocess with a
  2	//! pty as well as spinning up the necessary read thread to read from the
  3	//! pty and forward it to the Termio instance.
  4	const Exec = @This();
  5	
  6	const std = @import("std");
  7	const builtin = @import("builtin");
  8	const assert = @import("../quirks.zig").inlineAssert;
